mapper.select:
SELECT id, user_id, apartment_id, appointment_time, status, remark, create_time, create_by, update_time, update_by, is_delete FROM rental_view_appointment WHERE is_delete = 0
AND user_id = #{query.userId}
AND apartment_id = #{query.apartmentId}
AND status = #{query.status}
AND appointment_time >= #{query.appointmentTimeStart}
AND appointment_time <= #{query.appointmentTimeEnd}
ORDER BY id DESC
